import{_ as s}from"./chunks/dds.BF9YHakH.js";import{c as n,$ as r,Q as o,j as i,g as t,o as l,n as c,m as d}from"./chunks/framework.Ce_49mA8.js";const x=JSON.parse('{"title":"Cash Flow (DDS)","description":"Cash register management, cash and non-cash flows, mixed finances, personal owner investments, and expense processing in OmniCraft ERP.","frontmatter":{"title":"Cash Flow (DDS)","description":"Cash register management, cash and non-cash flows, mixed finances, personal owner investments, and expense processing in OmniCraft ERP.","datePublished":"2026-08-20","dateModified":"2026-11-25","order":3},"headers":[],"relativePath":"docs/resources/dds.md","filePath":"docs/resources/dds.md","lastUpdated":1795564800000}'),h={name:"docs/resources/dds.md"},p={id:"cash-flow-ledger-dds",tabindex:"-1"};function u(g,e,m,f,y,v){const a=r("DocIcon");return o(),i("div",null,[t("h1",p,[l(a,{name:"dds"}),e[0]||(e[0]=c(" Cash Flow Ledger (DDS) ",-1)),e[1]||(e[1]=t("a",{class:"header-anchor",href:"#cash-flow-ledger-dds","aria-label":'Permalink to "Cash Flow Ledger (DDS)"'},"​",-1))]),e[2]||(e[2]=d('<figure class="doc-image craft-window-frame" data-title="Cash Flow Ledger (DDS) — OmniCraft ERP"><img src="'+s+'" alt="Main window of the Cash Flow tab"><figcaption>Main window of the Cash Flow tab</figcaption></figure><p>The <strong>&quot;Cash Flow&quot; (DDS)</strong> tab serves as the centralized cash register and treasury hub for your business. Whether you operate a manufacturing workshop, run a repair service center, sell goods on online marketplaces, or work as an independent artisan, this tool monitors physical liquidity across cash drawers and bank accounts.</p><p>Unlike the &quot;Capital&quot; balance sheet, which tracks the overall net worth of your enterprise (including machinery, tools, warehouse raw materials, and finished goods), the Cash Flow module operates on a strict cash basis. It logs each unit of currency exclusively when it physically enters or leaves your accounts, safeguarding you against cash shortages.</p><hr><h2 id="cash-mechanics-three-key-indicators" tabindex="-1">Cash Mechanics: Three Key Indicators <a class="header-anchor" href="#cash-mechanics-three-key-indicators" aria-label="Permalink to &quot;Cash Mechanics: Three Key Indicators&quot;">​</a></h2><p>Three primary financial counters are situated in the upper dashboard, reflecting the real-time state of your cash position:</p><ol><li><strong>Actual Inflow (Cash):</strong> The sum of all monetary funds that physically arrived into your business (retail sales revenue, advance deposits on service work orders, diagnostic fees, masterclass tuition).</li><li><strong>Actual Outflow (Expenses):</strong> All funds physically disbursed (procurement of materials and spare parts, shipping fees, facility rent, advertising, digital services, taxes).</li><li><strong>Net Balance (Saldo):</strong> The difference between cumulative inflows and outflows at the current second.</li></ol><hr><h2 id="mixed-finances-philosophy-why-a-negative-balance-is-normal" tabindex="-1">Mixed Finances Philosophy: Why a Negative Balance is Normal <a class="header-anchor" href="#mixed-finances-philosophy-why-a-negative-balance-is-normal" aria-label="Permalink to &quot;Mixed Finances Philosophy: Why a Negative Balance is Normal&quot;">​</a></h2><p>In conventional corporate bookkeeping, a negative cash balance is considered a critical error. In the real world of small businesses, artisan workshops, and independent creators, the reality is different: at launch or during expansion, the founder pays for machinery, rent, and inventory out of personal savings or personal cards.</p><p>Requiring a founder to document formal shareholder loans for every routine purchase turns operations into bureaucratic chaos that quickly gets abandoned.</p><p><strong>OmniCraft ERP</strong> implements the natural law of <strong>mixed finances</strong>:</p><div class="tip custom-block"><p class="custom-block-title">A Negative Balance is an Honest Record of Founder Investment</p><p>A negative Cash Flow balance indicates that you invested personal capital into launching or expanding the business. The software truthfully logs this funding volume as a negative balance.</p><p>It provides a transparent answer to the question: <strong>&quot;How much money does the business owe back to you right now?&quot;</strong></p></div><p>As soon as the cash balance crosses zero and enters positive territory, it signals that the enterprise has fully repaid the founder&#39;s initial capital and has begun generating net cash profit.</p><hr><h2 id="practical-example-journey-from-founder-capital-to-net-profit" tabindex="-1">Practical Example: Journey from Founder Capital to Net Profit <a class="header-anchor" href="#practical-example-journey-from-founder-capital-to-net-profit" aria-label="Permalink to &quot;Practical Example: Journey from Founder Capital to Net Profit&quot;">​</a></h2><p>To visualize how a negative Cash Flow balance transforms into real profit, consider a standard business lifecycle:</p><div class="quickstart-steps-grid"><div class="step-card"><div class="step-header"><span class="step-num-badge">01</span><h3 class="step-title">Initial Investment</h3></div><p class="step-desc"> You invested personal capital: purchased machinery and tools for <strong>$1,500</strong>, raw materials for <strong>$500</strong>, and launched ads for <strong>$100</strong>.<br> • <strong>Cash Flow Saldo:</strong> <span style="color:var(--vp-c-danger);font-weight:600;">-$2,100</span> (volume of personal founder funding).<br> • <strong>Capital Balance:</strong> $2,000 (assets in machinery and raw materials). </p></div><div class="step-card"><div class="step-header"><span class="step-num-badge">02</span><h3 class="step-title">Fulfillment and Recovery</h3></div><p class="step-desc"> You completed a run of orders: used raw materials worth <strong>$200</strong>, machine wear was <strong>$20</strong>, and clients paid <strong>$800</strong>.<br> • <strong>Cash Flow Saldo:</strong> -$2,100 + $800 = <span style="color:var(--vp-c-danger);font-weight:600;">-$1,300</span> (cash is recovering investments).<br> • <strong>Capital Balance:</strong> $1,780 (tools $1,480 + raw materials $300). </p></div><div class="step-card"><div class="step-header"><span class="step-num-badge">03</span><h3 class="step-title">Break-even and Net Profit</h3></div><p class="step-desc"> You converted the remaining inventory (worth <strong>$300</strong>) and sold goods for another <strong>$1,500</strong>.<br> • <strong>Cash Flow Saldo:</strong> -$1,300 + $1,500 = <span style="color:var(--vp-c-success);font-weight:600;">+$200</span> (all $2,100 recovered, cash turned positive).<br> • <strong>Capital Balance:</strong> $1,450 (machinery remains valuable and continues earning). </p></div></div><hr><h2 id="cash-flow-specifics-across-industries" tabindex="-1">Cash Flow Specifics Across Industries <a class="header-anchor" href="#cash-flow-specifics-across-industries" aria-label="Permalink to &quot;Cash Flow Specifics Across Industries&quot;">​</a></h2><p>The nature of monetary flows varies depending on your operational profile:</p><h3 id="services" tabindex="-1">In the Service Sector <a class="header-anchor" href="#services" aria-label="Permalink to &quot;In the Service Sector {#services}&quot;">​</a></h3><p>In service workshops, electronics repair centers, and custom studios, deposits and job-specific parts play a central role:</p><ul><li><strong>Order deposits:</strong> client prepayments received when taking in a repair are immediately logged in cash, protecting you against unpaid custom parts orders.</li><li><strong>Component expenses:</strong> parts ordered for a specific work order are logged in the cash register upon procurement.</li><li><strong>Final settlement:</strong> when handing over the completed repair, the remaining payment for labor and parts enters the ledger upon work completion sign-off.</li></ul><h3 id="production" tabindex="-1">In Manufacturing and Crafts <a class="header-anchor" href="#production" aria-label="Permalink to &quot;In Manufacturing and Crafts {#production}&quot;">​</a></h3><p>In artisan workshops or batch production facilities, cash supports the material production cycle:</p><ul><li><strong>Bulk raw material lots:</strong> the cash ledger finances wholesale orders of sheet metal, leather, hardwood, or 3D resins.</li><li><strong>Logistics and freight:</strong> transport costs are recorded as a separate order, increasing the recorded unit cost of materials in the warehouse.</li><li><strong>Shop overhead:</strong> recurring monthly outlays (facility rent, industrial electricity, heating) are allocated to corresponding categories.</li></ul><h3 id="trade" tabindex="-1">In Retail and Marketplace Sellers <a class="header-anchor" href="#trade" aria-label="Permalink to &quot;In Retail and Marketplace Sellers {#trade}&quot;">​</a></h3><p>In e-commerce and retail storefronts, cash is synchronized with marketplace payment schedules:</p><ul><li><strong>Platform payouts:</strong> revenue does not arrive per individual receipt, but in scheduled batch transfers based on settlement reports minus platform commissions.</li><li><strong>Storage and fulfillment costs:</strong> warehousing and courier fees are entered as direct operating expenses.</li><li><strong>Customer refunds:</strong> customer returns trigger an expense entry linked to the original sales record.</li></ul><h3 id="masters" tabindex="-1">For Independent Artisans <a class="header-anchor" href="#masters" aria-label="Permalink to &quot;For Independent Artisans {#masters}&quot;">​</a></h3><p>For solo makers, OmniCraft ERP eliminates the immediate need to open complex corporate bank accounts on day one. You simply maintain clear separation between personal funds and workshop cash within a single interface.</p><hr><h2 id="cash-flow-sources-automated-vs-manual" tabindex="-1">Cash Flow Sources: Automated vs Manual <a class="header-anchor" href="#cash-flow-sources-automated-vs-manual" aria-label="Permalink to &quot;Cash Flow Sources: Automated vs Manual&quot;">​</a></h2><p>The financial engine relieves you of double data entry. Most cash ledger entries are created autonomously:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Transaction Source</th><th style="text-align:left;">Direction</th><th style="text-align:left;">How Entry is Generated</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Warehouse (Batch Procurement)</strong></td><td style="text-align:left;">Expense</td><td style="text-align:left;">The system automatically creates two orders: material purchase and freight delivery</td></tr><tr><td style="text-align:left;"><strong>Sales (Checkout Receipt)</strong></td><td style="text-align:left;">Income</td><td style="text-align:left;">Revenue is immediately deposited into cash upon completing a sale</td></tr><tr><td style="text-align:left;"><strong>Work Orders (Service Sector)</strong></td><td style="text-align:left;">Income</td><td style="text-align:left;">Deposit payments and final order closings increase the cash balance</td></tr><tr><td style="text-align:left;"><strong>Workshop (Asset Purchase)</strong></td><td style="text-align:left;">Expense</td><td style="text-align:left;">If machinery is marked as paid from cash, an expense order is generated</td></tr><tr><td style="text-align:left;"><strong>Online Storefront</strong></td><td style="text-align:left;">Income</td><td style="text-align:left;">Customer order confirmations add the transaction to the ledger</td></tr></tbody></table><h3 id="entering-miscellaneous-manual-transactions" tabindex="-1">Entering Miscellaneous (Manual) Transactions <a class="header-anchor" href="#entering-miscellaneous-manual-transactions" aria-label="Permalink to &quot;Entering Miscellaneous (Manual) Transactions&quot;">​</a></h3><p>All operational money movements not tied directly to standard finished goods sales are entered via the <strong>&quot;Add Other Transaction&quot;</strong> form on the right panel:</p><ol><li><strong>Transaction Type:</strong><ul><li><strong>Expense (Disbursement):</strong> operational costs of the enterprise (rent, cloud services, marketing).</li><li><strong>Non-operating Income:</strong> supplemental receipts (hosting a training masterclass, consulting, renting out equipment, selling scrap materials or offcuts).</li></ul></li><li><strong>Category Selection:</strong><ul><li><em>For expenses:</em> <strong>Advertising</strong>, <strong>Hosting &amp; Services</strong>, <strong>Facility Rent</strong>, <strong>Logistics</strong>, <strong>Equipment Maintenance</strong>, or the universal <strong>Other</strong> category.</li><li><em>For income:</em> <strong>Masterclass</strong>, <strong>Custom Services</strong>, <strong>Other</strong>.</li></ul></li><li><strong>Smart Amount Input:</strong> clicking the input field clears default zeroes automatically to accelerate form entry.</li><li><strong>Date Selection:</strong> transactions can be recorded under any past date using the integrated calendar.</li></ol><hr><p>Income or expenses posted by an external agent appear in the same cash flow ledger. To allow posting, enable Trusted Mode in <a href="./../global-settings">Global Settings</a>.</p><h2 id="dedicated-section-tax-payment" tabindex="-1">Dedicated Section: Tax Payment <a class="header-anchor" href="#dedicated-section-tax-payment" aria-label="Permalink to &quot;Dedicated Section: Tax Payment&quot;">​</a></h2><p>To avoid confusing tax obligations with routine operational expenses, a streamlined <strong>&quot;Tax Payment&quot;</strong> form is positioned at the bottom of the right panel:</p><ol><li>Specify the tax amount calculated for your current reporting period.</li><li>Select the actual payment date.</li><li>The system generates an expense record under the protected <strong>&quot;Taxes&quot;</strong> system category.</li></ol><p>These payments are isolated in analytical reports, allowing you to clearly monitor operating profit before taxes and net earnings after fiscal disbursements.</p><hr><h2 id="cash-register-log-and-financial-discipline" tabindex="-1">Cash Register Log and Financial Discipline <a class="header-anchor" href="#cash-register-log-and-financial-discipline" aria-label="Permalink to &quot;Cash Register Log and Financial Discipline&quot;">​</a></h2><p>The chronological ledger of all cash movements occupies the left half of the screen:</p><ul><li><strong>Color Accents:</strong> receipts are emphasized in green with a <strong>&quot;+&quot;</strong> sign, disbursements in red with a <strong>&quot;-&quot;</strong> sign.</li><li><strong>Pagination:</strong> the log displays records in blocks of 20 rows, ensuring smooth interface responsiveness even with thousands of yearly entries.</li><li><strong>Backdated Entries:</strong> when entering past operations, the program sets the timestamp to neutral noon <code>12:00:00</code>. This avoids timeline conflicts and preserves consistent daily opening and closing balances.</li></ul><h3 id="the-maker-s-golden-rule-never-confuse-revenue-with-personal-income" tabindex="-1">The Maker&#39;s Golden Rule: Never Confuse Revenue with Personal Income <a class="header-anchor" href="#the-maker-s-golden-rule-never-confuse-revenue-with-personal-income" aria-label="Permalink to &quot;The Maker&#39;s Golden Rule: Never Confuse Revenue with Personal Income&quot;">​</a></h3><p>A frequent cause of small business distress is the habit of withdrawing all cash revenue for personal spending immediately after a large sale.</p><div class="warning custom-block"><p class="custom-block-title">Cash Inflow is Not Pure Personal Salary</p><p>Until raw materials for the next production cycle, facility rent, and fiscal obligations are accounted for, those funds belong to the enterprise.</p><p>Withdraw money for personal consumption strictly via a dedicated expense transaction noted as <em>&quot;Owner Profit Distribution&quot;</em> or <em>&quot;Founder Salary&quot;</em>, maintaining a resilient working cash buffer in your business.</p></div><hr><h2 id="troubleshooting-common-pitfalls" tabindex="-1">Troubleshooting &amp; Common Pitfalls <a class="header-anchor" href="#troubleshooting-common-pitfalls" aria-label="Permalink to &quot;Troubleshooting &amp; Common Pitfalls&quot;">​</a></h2><div class="faq-grid"><details class="faq-item"><summary class="faq-summary">Why did cash flow turn negative and why doesn&#39;t the program block transactions?</summary><div class="faq-content"><p>A negative Cash Flow balance is normal during founder investment phases (purchasing leather, timber, or tooling before sales revenues arrive). OmniCraft ERP transparently tracks invested equity without artificial execution blocks.</p></div></details><details class="faq-item"><summary class="faq-summary">What should I do if a cash transaction was logged with the wrong amount or category?</summary><div class="faq-content"><p>Locate the transaction in the left register table and click the pencil edit icon. Update the amount, date, or category—the system recalculates opening and closing daily balances instantly across the entire timeline.</p></div></details><details class="faq-item"><summary class="faq-summary">Why does cash balance diverge from net profit in analytical reports?</summary><div class="faq-content"><p>Cash Flow tracks physical liquidity upon real movement (cash accounting method). Net profit is recognized upon delivery under accrual accounting, factoring in batch cost deductions and equipment depreciation.</p></div></details></div>',55))])}const q=n(h,[["render",u]]);export{x as __pageData,q as default};
